262	                case PipelineCommandKind.Count:
263	                    WriteAggregateCount(table, outputStream);
264	                    return;
265	                case PipelineCommandKind.Sum:
266	                    WriteAggregateSum(table, command.FirstArgument, outputStream);
267	                    return;
268	                case PipelineCommandKind.GroupByCount:
269	                    WriteGroupedCount(table, command.FirstArgument, outputStream);
270	                    return;
271	                case PipelineCommandKind.GroupBySum:
272	                    WriteGroupedSum(table, command.FirstArgument, command.SecondArgument ?? string.Empty, outputStream);
273	                    return;
274	                default:
275	                    throw new ArgumentOutOfRangeException();
276	            }
277	        }
278	
279	        WriteTable(table, outputStream);
280	    }
