332	    private static void WriteGroupedCount(CsvTable table, string groupColumnName, Stream outputStream)
333	    {
334	        var headerIndexes = BuildHeaderIndex(table.Headers);
335	        if (!headerIndexes.TryGetValue(groupColumnName, out var groupColumnIndex))
336	        {
337	            throw new InvalidOperationException($"Column not found: {groupColumnName}");
338	        }
