343	        foreach (var row in table.Rows)
344	        {
345	            var groupValue = GetValue(row, groupColumnIndex);
346	            if (!groupCounts.ContainsKey(groupValue))
347	            {
348	                groupOrder.Add(groupValue);
349	                groupCounts[groupValue] = 0;
350	            }
351	
352	            groupCounts[groupValue]++;
