354	
355	        using var writer = new StreamWriter(outputStream, leaveOpen: true)
356	        {
357	            NewLine = Environment.NewLine
358	        };
359	
360	        writer.WriteLine(string.Join(",", new[] { groupColumnName, "count" }));
361	        foreach (var groupValue in groupOrder)
362	        {
363	            writer.WriteLine(string.Join(",", new[] { groupValue, groupCounts[groupValue].ToString(System.Globalization.CultureInfo.InvariantCulture) }));
364	        }
