385	        foreach (var row in table.Rows)
386	        {
387	            var groupValue = GetValue(row, groupColumnIndex);
388	            var value = GetValue(row, valueColumnIndex);
389	            if (!decimal.TryParse(value, System.Globalization.NumberStyles.Number, System.Globalization.CultureInfo.InvariantCulture, out var numericValue))
390	            {
391	                throw new InvalidOperationException("All values in the target column must be numeric");
392	            }
393	
394	            if (!groupTotals.ContainsKey(groupValue))
395	            {
396	                groupOrder.Add(groupValue);
397	                groupTotals[groupValue] = 0m;
