148	                {
149	                    return false;
150	                }
151	
152	                commands.Add(new PipelineCommand(PipelineCommandKind.Sum, args[index + 1]));
153	                index += 2;
154	                return index == args.Length;
155	            }
156	            else if (IsCommand(token, "groupby"))
157	            {
158	                if (index + 2 >= args.Length)
159	                {
160	                    return false;
161	                }
162	
163	                var groupColumnName = args[index + 1];
164	                var aggregateName = args[index + 2];
165	
166	                if (IsCommand(aggregateName, "count"))
167	                {
168	                    commands.Add(new PipelineCommand(PipelineCommandKind.GroupByCount, groupColumnName));
169	                    index += 3;
170	                    return index == args.Length;
171	                }
172	
173	                if (IsCommand(aggregateName, "sum"))
174	                {
175	                    if (index + 3 >= args.Length)
176	                    {
177	                        return false;
178	                    }
179	
180	                    commands.Add(new PipelineCommand(PipelineCommandKind.GroupBySum, groupColumnName, args[index + 3]));
181	                    index += 4;
