617	    private static bool Matches(string leftValue, ComparisonOperator op, string rightValue)
618	    {
619	        if (TryParseNumber(leftValue, out var leftNumber) && TryParseNumber(rightValue, out var rightNumber))
620	        {
621	            return op switch
622	            {
623	                ComparisonOperator.Equal => leftNumber == rightNumber,
624	                ComparisonOperator.NotEqual => leftNumber != rightNumber,
625	                ComparisonOperator.GreaterThan => leftNumber > rightNumber,
626	                ComparisonOperator.LessThan => leftNumber < rightNumber,
627	                ComparisonOperator.GreaterThanOrEqual => leftNumber >= rightNumber,
628	                ComparisonOperator.LessThanOrEqual => leftNumber <= rightNumber,
629	                _ => throw new ArgumentOutOfRangeException(nameof(op), op, null)
630	            };
631	        }
632	
633	        var comparison = string.CompareOrdinal(leftValue, rightValue);
634	        return op switch
635	        {
636	            ComparisonOperator.Equal => comparison == 0,
637	            ComparisonOperator.NotEqual => comparison != 0,
638	            ComparisonOperator.GreaterThan => comparison > 0,
639	            ComparisonOperator.LessThan => comparison < 0,
640	            ComparisonOperator.GreaterThanOrEqual => comparison >= 0,
641	            ComparisonOperator.LessThanOrEqual => comparison <= 0,
642	            _ => throw new ArgumentOutOfRangeException(nameof(op), op, null)
643	        };
644	    }
