646	    private static bool TryParseNumber(string value, out decimal number)
647	    {
648	        return decimal.TryParse(
649	            value,
650	            System.Globalization.NumberStyles.Number,
651	            System.Globalization.CultureInfo.InvariantCulture,
652	            out number);
653	    }
