665	    private static ComparisonFilter ParseComparisonExpression(string expression)
666	    {
667	        var trimmed = expression.Trim();
668	        var operators = new[] { ">=", "<=", "!=", "=", ">", "<" };
669	
670	        foreach (var opText in operators)
671	        {
672	            var operatorIndex = trimmed.IndexOf(opText, StringComparison.Ordinal);
673	            if (operatorIndex <= 0)
674	            {
675	                continue;
676	            }
677	
678	            var columnName = trimmed[..operatorIndex].Trim();
679	            var value = trimmed[(operatorIndex + opText.Length)..].Trim();
680	            if (columnName.Length == 0 || value.Length == 0)
681	            {
682	                break;
683	            }
684	
685	            return new ComparisonFilter(columnName, ParseOperator(opText), value);
686	        }
687	
688	        throw new InvalidOperationException("Invalid comparison expression");
689	    }
690	
691	    private static ComparisonOperator ParseOperator(string opText)
692	    {
693	        return opText switch
694	        {
695	            "=" => ComparisonOperator.Equal,
696	            "!=" => ComparisonOperator.NotEqual,
697	            ">" => ComparisonOperator.GreaterThan,
698	            "<" => ComparisonOperator.LessThan,
699	            ">=" => ComparisonOperator.GreaterThanOrEqual,
700	            "<=" => ComparisonOperator.LessThanOrEqual,
701	            _ => throw new InvalidOperationException("Invalid comparison operator")
702	        };
703	    }
