705	    private static List<string> ParseCsvLine(string line)
706	    {
707	        var values = new List<string>();
708	        var current = new System.Text.StringBuilder();
709	        var inQuotes = false;
710	
711	        for (var i = 0; i < line.Length; i++)
712	        {
713	            var ch = line[i];
714	
715	            if (inQuotes)
716	            {
717	                if (ch == '"')
718	                {
719	                    if (i + 1 < line.Length && line[i + 1] == '"')
720	                    {
721	                        current.Append('"');
722	                        i++;
723	                    }
724	                    else
725	                    {
726	                        inQuotes = false;
727	                    }
728	                }
729	                else
730	                {
731	                    current.Append(ch);
732	                }
733	            }
734	            else if (ch == ',')
735	            {
736	                values.Add(current.ToString());
737	                current.Clear();
738	            }
739	            else if (ch == '"')
740	            {
741	                inQuotes = true;
742	            }
743	            else
744	            {
745	                current.Append(ch);
746	            }
747	        }
748	
749	        values.Add(current.ToString());
750	        return values;
751	    }
